mapper.select:
SELECT r.id, r.dish_id AS dishId, d.name AS dishName, d.image AS dishImage, s.id AS stallId, s.name AS stallName, r.user_id AS userId, CASE WHEN r.anonymous = 1 THEN '匿名用户' ELSE IFNULL(u.real_name, '已注销用户') END AS userName, CASE WHEN r.anonymous = 1 THEN '' ELSE IFNULL(u.avatar, '') END AS avatar, r.rating, r.content, r.anonymous, r.status,
(r.user_id = #{currentUserId}) AS mine
0 AS mine
, r.create_time AS createTime FROM dish_review r INNER JOIN dish d ON r.dish_id = d.id AND d.deleted = 0 LEFT JOIN canteen_stall s ON d.stall_id = s.id AND s.deleted = 0 LEFT JOIN sys_user u ON r.user_id = u.id AND u.deleted = 0 WHERE r.deleted = 0
AND r.dish_id = #{query.dishId}
AND r.user_id = #{query.userId}
AND d.stall_id = #{query.stallId}
AND r.rating = #{query.rating}
AND r.status = #{query.status}
AND (r.content LIKE CONCAT('%', #{query.keyword}, '%') OR d.name LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY r.create_time DESC
